examples.code:
new ToastBuilder("Uploading...")
  .withDuration(6000)
  .withProgress({ mode: "drain", color: "#28a6f5" })
  .withOnClose(() => {
    new ToastBuilder("Upload complete!")
      .withColor(ToastColor.SUCCESS)
      .show();
  })
  .show();

new ToastBuilder("First")
  .withPosition(ToastPosition.TOP_RIGHT)
  .show();
new ToastBuilder("Second")
  .withPosition(ToastPosition.TOP_RIGHT)
  .show();
new ToastBuilder("Inserted at the far end")
  .withPosition(ToastPosition.TOP_RIGHT)
  .andReverseOrder()
  .show();

new ToastBuilder("Custom themed toast")
  .withTheme({
    background: "#1c1c1c",
    text: "#f5f5f5",
    actionColor: "#4bb543"
  })
  .show();

new ToastBuilder("Update available")
  .withDuration(0)
  .withButton("Reload", () => {
    new ToastBuilder("Reloaded successfully!")
      .withColor(ToastColor.SUCCESS)
      .show();
  })
  .withCloseButton("Dismiss")
  .show();

new ToastBuilder('Check out <b>this</b> and <a href="#">this link</a>!')
  .withAllowHtml(true)
  .show();
